// Display and input validation only. Python supplies all exact recoupling data.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>{const n=Number(value);return !Number.isFinite(n)?'—':n===0?'0':Math.abs(n)<1e-5?n.toExponential(4):Number(n.toFixed(6)).toString();};
const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const reps=[['0,0','1 · (0, 0)'],['1,0','3 · (1, 0)'],['0,1','3̄ · (0, 1)'],['2,0','6 · (2, 0)'],['0,2','6̄ · (0, 2)'],['1,1','8 · (1, 1)']];
const repSize=([p,q])=>(p+1)*(q+1)*(p+q+2)/2;
const repLabel=item=>item?.label||`(${item?.p??0}, ${item?.q??0})`;
const allTargets=Array.from({length:7},(_,sum)=>Array.from({length:sum+1},(_,q)=>{const p=sum-q;return [`${p},${q}`,`${repSize([p,q])} dimension · (${p}, ${q})`];})).flat();
const initialTargets=[['auto',"automatically selects the actual representation"],...allTargets];
const exactParts=value=>typeof value==='object'&&value!==null?{re:String(value.re??'0'),im:String(value.im??'0')}:{re:String(value??'0'),im:'0'};
const exactComplex=value=>{const {re,im}=exactParts(value);return im==='0'?re:re==='0'?`(${im})i`:`${re} + (${im})i`;};
const complex=value=>{const re=Number(value?.re??value??0),im=Number(value?.im??0);return im===0?fmt(re):re===0?`${fmt(im)}i`:`${fmt(re)} ${im<0?'−':'+'} ${fmt(Math.abs(im))}i`;};
const pathLabel=(path,index)=>path?.label||`path ${index}`;
const parity=value=>value===1?"+ Symmetry":value===-1?"− Antisymmetric":'—';
const targetItems=targets=>targets.map(item=>[`${item.p},${item.q}`,`${repLabel(item)} · (${item.p}, ${item.q}) · multiplicity ${item.multiplicity}`]);
const selectedMultiplicity=$=>$('#lg-racah-target')?._racahTargets?.find(item=>`${item.p},${item.q}`===$('#lg-racah-target').value)?.multiplicity;
const vectorHint=m=>`Fill in${m?` ${m} Term`:"The multiplicity item selected for the final representation (calculated first in single path state, multiplicity can be read)"}. Each item is a real number, a radical string, or {"re":"sqrt(2)/2","im":"1/3"}. The overall norm remains unchanged; Python checks expression and vector dimensions.`;
export const racahName="SU(3) · Racah（6j） and triple recoupling";
export const racahDefault={factors:[[1,0],[1,0],[1,0]],target:[1,1],direction:'left_to_right',state:{index:0}};
export const racahPresets={
  'racah-three-three-three':{experiment:'su3_racah',input:structuredClone(racahDefault)},
  'racah-three-bar-three':{experiment:'su3_racah',input:{factors:[[1,0],[0,1],[1,0]],target:[1,0],direction:'left_to_right',state:{index:0}}},
  'racah-six-three-three':{experiment:'su3_racah',input:{factors:[[2,0],[1,0],[1,0]],target:[2,1],direction:'left_to_right',state:{index:0}}},
  'racah-eight-eight-eight':{experiment:'su3_racah',input:{factors:[[1,1],[1,1],[1,1]],target:[1,1],direction:'left_to_right',state:{index:0}}},
  'racah-exact-complex':{experiment:'su3_racah',input:{...structuredClone(racahDefault),state:{amplitudes:[{re:'sqrt(2)/2',im:'0'},{re:'0',im:'sqrt(2)/2'}]}}},
};
export const racahInputIds=['#lg-racah-factor1','#lg-racah-factor2','#lg-racah-factor3','#lg-racah-target','#lg-racah-direction','#lg-racah-mode','#lg-racah-index','#lg-racah-vector'];
export function racahControls(input){
  const custom=Array.isArray(input.state?.amplitudes),dimension=input.factors.map(repSize).reduce((a,b)=>a*b,1);
  return `${[1,2,3].map(i=>`<label>No. ${i} SU(3) factors<select id="lg-racah-factor${i}">${options(reps,input.factors[i-1].join(','))}</select></label>`).join('')}<label>Final irreducible representation D<select id="lg-racah-target">${options(initialTargets,input.target?.join(',')||'auto')}</select><span class="lg-muted" id="lg-racah-target-hint" role="status">After calculation, Python lists the final representations that actually appear in this group of triple products and multiplicity .</span></label><label>recoupling Direction<select id="lg-racah-direction">${options([['left_to_right',"left tree ((A B) C) → right tree (A (B C))"],['right_to_left',"Right tree (A (B C)) → Left tree ((A B) C)"]],input.direction)}</select></label><label>input channel status<select id="lg-racah-mode">${options([['basis',"a coupling path state"],['vector',"Custom complex amplitude superposition state"]],custom?'vector':'basis')}</select></label><label>Input path index (starting from 0)<input id="lg-racah-index" type="number" min="0" max="511" step="1" value="${custom?0:esc(input.state?.index??0)}"><span class="lg-muted" id="lg-racah-size-hint">triple product space ${dimension} dimension; the calculation is done in the multiplicity space of fixed D.</span></label><label class="lg-cg-vector-label">multiplicity spatial complex amplitude (JSON)<textarea id="lg-racah-vector" rows="4" spellcheck="false" placeholder='["sqrt(2)/2", {"re":"0","im":"sqrt(2)/2"}]'>${custom?esc(JSON.stringify(input.state.amplitudes)):''}</textarea><span class="lg-muted" id="lg-racah-vector-hint">${esc(vectorHint())}</span></label><div class="lg-presets"><button type="button" data-lg-physics-preset="racah-three-three-three">recoupling · 3 ⊗ 3 ⊗ 3 → 8</button><button type="button" data-lg-physics-preset="racah-three-bar-three">recoupling · 3 ⊗ 3̄ ⊗ 3 → 3</button><button type="button" data-lg-physics-preset="racah-six-three-three">recoupling · 6 ⊗ 3 ⊗ 3 → 15</button><button type="button" data-lg-physics-preset="racah-eight-eight-eight">recoupling · 8 ⊗ 8 ⊗ 8 → 8</button><button type="button" data-lg-physics-preset="racah-exact-complex">Accurate complex phase with recoupling round trip</button></div><p class="lg-hint">has three optional factors: 1, 3, 3̄, 6, 6̄, and 8; the total number of dimensions is up to 512. First calculation loads SymPy. The results include the exact radical, the copy label outer multiplicity , and GT phase convention for this experiment. F acts to fix the channel coordinates of the final representation; recoupling itself does not produce time evolution.</p>`;
}
function readFactors($){return [1,2,3].map(i=>{const value=$('#lg-racah-factor'+i)?.value;if(!reps.some(([key])=>key===value))throw Error("Please select the three factors from 1, 3, 3̄, 6, 6̄, and 8.");return value.split(',').map(Number);});}
export function readRacahPayload($,read){
  const factors=readFactors($),key=$('#lg-racah-target')?.value,direction=$('#lg-racah-direction')?.value,mode=$('#lg-racah-mode')?.value,m=selectedMultiplicity($);
  if(key!=='auto'&&!allTargets.some(([item])=>item===key))throw Error("Please select a valid final SU(3) representation.");
  if(!['left_to_right','right_to_left'].includes(direction))throw Error("Please select a valid recoupling direction.");
  if(!['basis','vector'].includes(mode))throw Error("Please select a path state or a custom superposition state.");
  let state;
  if(mode==='basis')state={index:read('#lg-racah-index',0,m?m-1:511,true)};
  else{
    let amplitudes;try{amplitudes=JSON.parse($('#lg-racah-vector')?.value||'');}catch{throw Error("multiplicity The spatial complex amplitude needs to be a valid JSON array.");}
    if(!Array.isArray(amplitudes)||amplitudes.length<1||amplitudes.length>512||m&&amplitudes.length!==m)throw Error(m?`Multiplicity of the current final representation: ${m}, the complex amplitude vector must contain ${m} item.`:"complex amplitude vector needs to contain 1 to 512 entries; Python will check it against the target multiplicity .");
    const scalar=value=>typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)<=1e6||typeof value==='string'&&value.trim().length>0&&value.length<=65536&&/^[\d\s+*/()\-]+$/.test(value.replaceAll('sqrt',''));
    if(amplitudes.some(value=>typeof value==='number'||typeof value==='string'?!scalar(value):!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).some(key=>!['re','im'].includes(key))||!scalar(Object.hasOwn(value,'re')?value.re:0)||!scalar(Object.hasOwn(value,'im')?value.im:0)))throw Error("amplitude allows limited real numbers or integers, rational numbers, four arithmetic operations and sqrt (non-negative integer) strings; complex numbers are filled in with re and im objects.");
    state={amplitudes:amplitudes.map(value=>typeof value==='object'?{re:value.re??0,im:value.im??0}:{re:value,im:0})};
    if(state.amplitudes.reduce((sum,z)=>sum+Object.values(z).reduce((n,value)=>n+(typeof value==='string'?value.length:0),0),0)>1048576)throw Error("The total length of expressions for exact input vectors is limited to 1 MiB.");
  }
  return {factors,...(key==='auto'?{}:{target:key.split(',').map(Number)}),direction,state};
}
export function bindRacahControls(root,current){
  const $=selector=>root.querySelector(selector),refresh=()=>{if(!current())return;try{const dimension=readFactors($).map(repSize).reduce((a,b)=>a*b,1),m=selectedMultiplicity($),custom=$('#lg-racah-mode').value==='vector',index=$('#lg-racah-index');index.max=String(m?m-1:511);if(m&&Number(index.value)>=m)index.value='0';index.disabled=custom;$('#lg-racah-vector').disabled=!custom;$('#lg-racah-size-hint').textContent=`triple product space ${dimension} dimension;${m?`The multiplicity space of selected D is ${m} dimension, path index 0–${m-1}。`:"calculation is done in the multiplicity space of fixed D."}`;$('#lg-racah-vector-hint').textContent=vectorHint(m);}catch{/* Submission gives a useful error. */}};
  for(const i of [1,2,3])if($('#lg-racah-factor'+i))$('#lg-racah-factor'+i).onchange=()=>{if(!current())return;const target=$('#lg-racah-target');target._racahTargets=null;target.innerHTML=options(initialTargets,'auto');target.value='auto';$('#lg-racah-index').value='0';$('#lg-racah-target-hint').textContent="The factors have been changed; the actual occurrence of the target is automatically selected and the full decomposition and multiplicity are listed after calculation.";refresh();};
  for(const id of ['#lg-racah-target','#lg-racah-mode'])if($(id))$(id).onchange=refresh;
  refresh();
}
function amplitudes(paths,values,exact,probabilities,exactProbabilities,caption){
  return `<div class="lg-table-scroll"><table class="lg-data-table lg-cg-amplitudes"><caption>${esc(caption)}</caption><thead><tr><th>Index · coupling path</th><th>precise complex amplitude</th><th>numerical approximation</th><th>Normalized channel probability</th></tr></thead><tbody>${values.map((value,index)=>({value,index})).filter(({index})=>exact?exactComplex(exact[index])!=='0':probabilities[index]>1e-20).map(({value,index})=>`<tr><td>${index} · ${esc(pathLabel(paths[index],index))}</td><td class="lg-cg-exact"><code>${esc(exactComplex(exact?.[index]??value))}</code></td><td>${esc(complex(value))}</td><td><code>${esc(exactProbabilities?.[index]??fmt(probabilities[index]))}</code><br><progress max="1" value="${esc(probabilities[index])}" aria-label="path ${index} "></progress> ≈ ${fmt(probabilities[index])}</td></tr>`).join('')}</tbody></table></div>`;
}
function pathTable(result){
  return `<details class="lg-generator"><summary>All coupling path and outer multiplicity tags</summary>${[['leftPaths',"Zuoshu · ((A B) C)"],['rightPaths',"Right tree · (A (B C))"]].map(([key,title])=>`<div class="lg-table-scroll"><table class="lg-data-table"><caption>${title}</caption><thead><tr><th>path</th><th>intermediate representation</th><th>First vertex copy</th><th>Second vertex copy</th><th>The first/second vertex exchange parity</th></tr></thead><tbody>${result[key].map((path,index)=>`<tr><td>${index} · ${esc(pathLabel(path,index))}</td><td>${esc(repLabel(path.intermediate))} (${path.intermediate.p}, ${path.intermediate.q})</td><td>${esc(path.firstCopy)}</td><td>${esc(path.secondCopy)}</td><td>${parity(path.firstSwapParity)} ／ ${parity(path.secondSwapParity)}</td></tr>`).join('')}</tbody></table></div>`).join('')}<p class="lg-hint">firstCopy and secondCopy respectively mark two outer multiplicity copies of the CG vertex. The same intermediate representation can produce different paths; each path remains in a separate row or column of F. Swapping parity only applies if the corresponding two input representations are identical.</p></details>`;
}
function trees(result,leftIndex=0,rightIndex=0){
  const short=item=>repLabel(item).replace(/\s*\([^)]*\).*$/,''),[a,b,c]=result.factors.map(short),d=short(result.target),left=result.leftPaths[leftIndex],right=result.rightPaths[rightIndex],node=(x,y,text,kind='')=>`<g class="${kind}"><rect x="${x-36}" y="${y-19}" width="72" height="38" rx="8"/><text x="${x}" y="${y+6}" text-anchor="middle">${esc(text)}</text></g>`,edge=(x,y,xx,yy)=>`<path d="M${x},${y} L${xx},${yy}"/>`;
  return `<svg class="lg-visual lg-racah-tree" viewBox="0 0 680 280" role="img" aria-label="Selected left and right coupling tree and middle representation"><title>The left tree couples A and B first; the right tree couples B and C first. The replica number for each vertex is reserved outer multiplicity .</title><g class="lg-racah-branches">${edge(64,64,114,133)}${edge(164,64,114,133)}${edge(114,171,164,221)}${edge(264,64,164,221)}${edge(416,64,516,221)}${edge(516,64,566,133)}${edge(616,64,566,133)}${edge(566,171,516,221)}</g>${node(64,45,a)}${node(164,45,b)}${node(264,45,c)}${node(114,152,short(left.intermediate),'lg-racah-intermediate')}${node(164,240,d)}${node(416,45,a)}${node(516,45,b)}${node(616,45,c)}${node(566,152,short(right.intermediate),'lg-racah-intermediate')}${node(516,240,d)}<text x="335" y="143" text-anchor="middle" class="lg-racah-arrow">F</text><text x="164" y="100" class="lg-racah-copy">α=${esc(left.firstCopy)}</text><text x="215" y="201" class="lg-racah-copy">β=${esc(left.secondCopy)}</text><text x="416" y="201" class="lg-racah-copy">δ=${esc(right.secondCopy)}</text><text x="462" y="100" class="lg-racah-copy">γ=${esc(right.firstCopy)}</text></svg><p class="lg-hint">left path ${leftIndex}：${esc(pathLabel(left,leftIndex))}<br>right path ${rightIndex}：${esc(pathLabel(right,rightIndex))}</p>`;
}
function matrixView(result,view='F',leftIndex=0,rightIndex=0){
  const six=view==='sixJ',values=six?result.sixJMatrix:result.fMatrix,exact=six?result.exactSixJMatrix:result.exactFMatrix,m=result.multiplicity,cell=Math.min(78,360/m),extent=cell*m,offset=68,label=six?'6j':'F';
  return `<p class="lg-racah-matrix-convention">${six?"The dimensionality reduction six-label coefficient defined in this experiment: 6j[R,L] = F[R,L] / √(dim Eₗ · dim Fᵣ). This table is labeled with four copies of outer multiplicity ; directly change of basis uses F.":"unitary recoupling matrix F[R,L] = ⟨ right path R; D,m | left path L; D,m⟩. The rows correspond to the right tree, and the columns correspond to the left tree; the same internal state m of D is fixed."}</p><svg class="lg-visual lg-racah-heatmap" viewBox="0 0 ${extent+100} ${extent+108}" role="img" aria-label="${six?"six label coefficients":"F recoupling matrix"}accurate coefficient heat map"><title>Row: Right path index; Column: Left path index. Blue is positive, orange is negative; hover to see the exact value.</title><text x="${offset+extent/2}" y="23" text-anchor="middle" class="lg-svg-label">column: left tree path L</text>${values.map((row,i)=>row.map((value,j)=>`<rect x="${offset+j*cell}" y="${58+i*cell}" width="${cell}" height="${cell}" fill="${value<0?'#b7863c':value>0?'#4383a2':'#f1f5eb'}" fill-opacity="${value===0?1:.2+.8*Math.min(1,Math.abs(value))}" stroke="${i===rightIndex&&j===leftIndex?'#355a38':'white'}" stroke-width="${i===rightIndex&&j===leftIndex?3:1}"><title>${label}[${i}, ${j}] = ${esc(exact[i][j])}; ${esc(pathLabel(result.rightPaths[i],i))} ← ${esc(pathLabel(result.leftPaths[j],j))}</title></rect>`)).flat().join('')}${Array.from({length:m},(_,i)=>`<text x="${offset+(i+.5)*cell}" y="47" text-anchor="middle" class="lg-cg-axis">${i}</text><text x="55" y="${58+(i+.55)*cell}" text-anchor="end" class="lg-cg-axis">${i}</text>`).join('')}<text x="${offset+extent/2}" y="${extent+94}" text-anchor="middle" class="lg-svg-label">row: right tree path R</text></svg><div class="lg-table-scroll lg-racah-matrix"><table class="lg-data-table"><caption>${label} · Complete accurate coefficient table (${m} × ${m}）</caption><thead><tr><th>Right R / Left L</th>${result.leftPaths.map((path,j)=>`<th title="${esc(pathLabel(path,j))}">L${j}</th>`).join('')}</tr></thead><tbody>${values.map((row,i)=>`<tr><th title="${esc(pathLabel(result.rightPaths[i],i))}">R${i}</th>${row.map((value,j)=>`<td class="${i===rightIndex&&j===leftIndex?'lg-racah-selected':''}"><code>${esc(exact[i][j])}</code><small>≈ ${fmt(value)}</small></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="lg-racah-selected-value" role="status">${label}[R${rightIndex}, L${leftIndex}] = <code>${esc(exact[rightIndex][leftIndex])}</code> ≈ ${fmt(values[rightIndex][leftIndex])}</p>`;
}
const checkNames={unitarity:"unitary relationship",pathOrthogonality:"path orthogonal normalization",reconstruction:"tree base reconstruction",gtStateIndependence:"GT Internal state independence",weightedSixJ:"6j weighted orthogonal",multiplicity:"Path multiplicity",stateNorm:"state norm",roundtrip:"Round trip recoupling"};
export function racahOutput(result){
  const forward=result.direction==='left_to_right',outputPaths=forward?result.rightPaths:result.leftPaths,inputPaths=forward?result.leftPaths:result.rightPaths;
  return `<pre class="lg-formula">${esc(result.factors.map(repLabel).join(' ⊗ '))} → D = ${esc(repLabel(result.target))} (${result.target.p}, ${result.target.q})
triple product dimension ${result.dimension}; D’s multiplicity ${result.multiplicity}
b right = F a left; a left = F† b right</pre><p class="lg-cg-mode-result">Exact symbol recoupling · ${result.multiplicity} × ${result.multiplicity}</p><p>Python Construct two coupling tree trees using the same set of GT bases and CG phases, and calculate their exact overlap. The table below shows the channel coordinates of the fixed final representation D.</p><p class="lg-cg-exact-norm">Exact norm squared:<code>${esc(result.exactInputNorm)}</code> → <code>${esc(result.exactOutputNorm)}</code>; Numerical verification ${fmt(result.inputNorm)} → ${fmt(result.outputNorm)}</p>${amplitudes(outputPaths,result.outputAmplitudes,result.exactOutputAmplitudes,result.outputProbabilities,result.exactOutputProbabilities,"The non-zero channel amplitude after this recoupling")}<p class="lg-hint">Channel probabilities are normalized by the input state norm; it describes the expansion of the same state in another coupling order. The sign and phase of F affect the interference of superposition states.</p><button type="button" class="secondary" id="lg-racah-reverse-state">Take full accurate output as input, reverse recoupling</button><details class="lg-generator"><summary>Check this recoupling input status</summary>${amplitudes(inputPaths,result.inputAmplitudes,result.exactInputAmplitudes,result.inputProbabilities,result.exactInputProbabilities,"The channel coordinates input this time")}</details><section class="lg-racah-inspector"><h4>Compare the left and right two coupling path</h4><div class="lg-racah-path-selectors"><label>left tree path L<select id="lg-racah-left">${options(result.leftPaths.map((path,i)=>[i,`${i} · ${pathLabel(path,i)}`]),0)}</select></label><label>right tree path R<select id="lg-racah-right">${options(result.rightPaths.map((path,i)=>[i,`${i} · ${pathLabel(path,i)}`]),0)}</select></label></div><div class="lg-actions"><button type="button" class="secondary" id="lg-racah-use-left">With the left path selected as the initial state, recoupling goes to the right tree</button><button type="button" class="secondary" id="lg-racah-use-right">With the right path selected as the initial state, recoupling goes to the left tree</button></div><div id="lg-racah-tree-panel">${trees(result)}</div><label class="lg-filter">matrix and coefficient convention<select id="lg-racah-matrix-view">${options([['F',"F · Unitary Racah recoupling matrix"],['sixJ',"6j · Divide by the middle representation dimension factor"]], 'F')}</select></label><div id="lg-racah-matrix-panel">${matrixView(result)}</div></section>${pathTable(result)}<details class="lg-generator"><summary>Complete Triple tensor product Breakdown and Target multiplicity</summary><div class="lg-table-scroll"><table class="lg-data-table"><thead><tr><th>finally means D</th><th>Dynkin Tags</th><th>Dimensions per copy</th><th>outer multiplicity</th></tr></thead><tbody>${(result.targets||[]).map(item=>`<tr><td>${esc(repLabel(item))}</td><td>(${item.p}, ${item.q})</td><td>${item.dimension}</td><td>${item.multiplicity}</td></tr>`).join('')}</tbody></table></div></details><section class="lg-cg-exact-checks" aria-label="recoupling Accurate symbol verification"><h4>accurate symbol verification</h4><p>Signed residual 0 means that the corresponding identity relationship is accurately established.</p><div class="lg-checks">${Object.entries(result.exactChecks||{}).map(([key,value])=>`<div><span>${esc(checkNames[key]||key)}</span><code>${esc(value)}</code></div>`).join('')}</div></section><details class="lg-generator"><summary>Numerical check residual</summary><div class="lg-checks">${Object.entries(result.checks||{}).map(([key,value])=>`<div><span>${esc(checkNames[key]||key)}</span><code>${Number(value).toExponential(2)}</code></div>`).join('')}</div></details><details class="lg-generator"><summary>recoupling , six-label coefficients and phase convention</summary>${(Array.isArray(result.convention)?result.convention:[result.convention||'']).map(note=>`<p>${esc(note)}</p>`).join('')}<ol>${(result.derivation||[]).map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details>`;
}
export function bindRacahOutput(root,result,current,runWithInput){
  const $=selector=>root.querySelector(selector),valid=id=>{const index=Number($(id)?.value);return Number.isInteger(index)&&index>=0&&index<result.multiplicity?index:0;};
  const target=$('#lg-racah-target');if(target){target._racahTargets=result.targets;const key=`${result.target.p},${result.target.q}`;target.innerHTML=options(targetItems(result.targets),key);target.value=key;$('#lg-racah-target-hint').textContent="The above is the complete decomposition of this group of triple products returned by Python; recalculate after switching D.";target.onchange?.();}
  const redraw=()=>{if(!current())return;const left=valid('#lg-racah-left'),right=valid('#lg-racah-right'),view=$('#lg-racah-matrix-view').value;if(!['F','sixJ'].includes(view))return;$('#lg-racah-tree-panel').innerHTML=trees(result,left,right);$('#lg-racah-matrix-panel').innerHTML=matrixView(result,view,left,right);};
  for(const id of ['#lg-racah-left','#lg-racah-right','#lg-racah-matrix-view'])if($(id))$(id).onchange=redraw;
  for(const [id,direction,selector] of [['#lg-racah-use-left','left_to_right','#lg-racah-left'],['#lg-racah-use-right','right_to_left','#lg-racah-right']])if($(id))$(id).onclick=()=>{if(!current()||typeof runWithInput!=='function')return;return runWithInput({direction,state:{index:valid(selector)}});};
  if($('#lg-racah-reverse-state'))$('#lg-racah-reverse-state').onclick=()=>{if(!current()||typeof runWithInput!=='function')return;return runWithInput({direction:result.direction==='left_to_right'?'right_to_left':'left_to_right',state:{amplitudes:result.exactOutputAmplitudes.map(exactParts)}});};
}
